cat > src/main.rs <<'EOF'
use std::collections::HashMap;
use std::io::{self, BufWriter, Write};

#[derive(Clone, Copy)]
enum Total {
    Sum(i64),
    Overflow,
}

fn strip_cr(line: &[u8]) -> &[u8] {
    line.strip_suffix(b"\r").unwrap_or(line)
}

fn main() -> io::Result<()> {
    let path = match std::env::args_os().nth(1) {
        Some(p) => p,
        None => return Ok(()),
    };
    let data = std::fs::read(path)?;

    let mut lines: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
    // A trailing newline leaves one empty piece that is not a line.
    if lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }

    let mut totals: HashMap<&[u8], Total> = HashMap::new();
    let mut idx = 0;
    while idx < lines.len() {
        let line = strip_cr(lines[idx]);
        idx += 1;
        if line.is_empty() {
            break;
        }
        let (key, rest) = match line.iter().position(|&b| b == b' ') {
            Some(p) => (&line[..p], &line[p + 1..]),
            None => continue,
        };
        let value = match std::str::from_utf8(rest.trim_ascii())
            .ok()
            .and_then(|s| s.parse::<i64>().ok())
        {
            Some(v) => v,
            None => continue,
        };
        let entry = totals.entry(key).or_insert(Total::Sum(0));
        *entry = match *entry {
            Total::Sum(s) => s.checked_add(value).map_or(Total::Overflow, Total::Sum),
            Total::Overflow => Total::Overflow,
        };
    }

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for raw in &lines[idx..] {
        let key = strip_cr(raw);
        out.write_all(key)?;
        match totals.get(key) {
            None => out.write_all(b"=absent\n")?,
            Some(Total::Overflow) => out.write_all(b"=overflow\n")?,
            Some(Total::Sum(s)) => writeln!(out, "={s}")?,
        }
    }
    out.flush()
}
